/**
 * Wrapper for user-supplied custom ID generator functions.
 *
 * We validate the generator at configuration time and again at call time so
 * errors surface with clear messages rather than cryptic TypeErrors deep in
 * middleware execution.
 */

/**
 * Validate that a value is a callable custom generator.
 * @param {unknown} generator
 * @throws {TypeError}
 */
export function assertValidGenerator(generator) {
  if (typeof generator !== "function") {
    throw new TypeError(
      `[@mohammed_kashif/requestid] options.generator must be a function, ` +
      `got: ${typeof generator}`
    );
  }
}

/**
 * Call a custom generator, coerce the result to a non-empty string, and
 * surface clear errors if the generator misbehaves.
 *
 * @param {Function} generator
 * @returns {string}
 */
export function invokeCustomGenerator(generator) {
  let result;

  try {
    result = generator();
  } catch (err) {
    throw new Error(
      `[@mohammed_kashif/requestid] Custom generator threw an error: ${err.message}`,
      { cause: err }
    );
  }

  if (typeof result !== "string" || result.trim() === "") {
    throw new TypeError(
      `[@mohammed_kashif/requestid] Custom generator must return a non-empty string, ` +
      `got: ${JSON.stringify(result)}`
    );
  }

  return result;
}
